import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { updateOrderEditShippingMethodWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await updateOrderEditShippingMethodWorkflow(req.scope)
    .run({
      input: {
        order_id: "order_123",
        action_id: "orchac_123",
        data: {
          custom_amount: 10,
        }
      }
    })

  res.send(result)
}

